window.docContents[42].resolve({"/5___-Representations-of-finite-groups___-Further-results/5___7___-Virtual-representations/Virtual-representation-with-inner-product-1-and-positive-dimension-is-irreducible/#Chapter5___Lemma5___7___2":{"contents":"Lemma 5.7.2. Let V be a virtual representation with character \\chi_V. If (\\chi_V, \\chi_V) = 1 and \\chi_V(1) > 0, then \\chi_V is a character of an irreducible representation of G.\n\nProof. Let V_1, V_2, \\ldots, V_m be the irreducible representations of G, and let V = \\sum n_i V_i. Then by orthonormality of characters, (\\chi_V, \\chi_V) = \\sum_i n_i^2. So \\sum_i n_i^2 = 1, meaning that n_i = \\pm 1 for exactly one i and n_j = 0 for j \\neq i. But \\chi_V(1) > 0, so n_i = +1 and we are done. \\square\n\n\n\n","context":"Introduction to Representation Theory\t5. Representations of finite groups: Further results\t5.7. Virtual representations\tVirtual representation with inner product 1 and positive dimension is irreducible","header":"Virtual representation with inner product 1 and positive dimension is irreducible","id":"/5___-Representations-of-finite-groups___-Further-results/5___7___-Virtual-representations/Virtual-representation-with-inner-product-1-and-positive-dimension-is-irreducible/#Chapter5___Lemma5___7___2"},"/5___-Representations-of-finite-groups___-Further-results/5___1___-Frobenius-Schur-indicator/Sum-of-dimensions-equals-number-of-involutions-when-all-reps-are-real/#Chapter5___Corollary5___1___6":{"contents":"Corollary 5.1.6. Assume that all representations of a finite group G are defined over real numbers (i.e., all complex representations of G are obtained by complexifying real representations). Then the sum of the dimensions of all the irreducible representations of G equals the number of involutions in G.\n\n\n\n","context":"Introduction to Representation Theory\t5. Representations of finite groups: Further results\t5.1. Frobenius-Schur indicator\tSum of dimensions equals number of involutions when all reps are real","header":"Sum of dimensions equals number of involutions when all reps are real","id":"/5___-Representations-of-finite-groups___-Further-results/5___1___-Frobenius-Schur-indicator/Sum-of-dimensions-equals-number-of-involutions-when-all-reps-are-real/#Chapter5___Corollary5___1___6"}});
